/** @type {import('next').NextConfig} */
const nextConfig = {
  transpilePackages: ['@juspay-tech/hyper-js', '@juspay-tech/react-hyper-js'],
  async rewrites() {
    return [
      {
        source: '/create-payment',
        destination: 'http://localhost:4242/create-payment' // Proxy to Backend
      }
    ]
  },
}

module.exports = nextConfig

const express = require("express");
const app = express();
// This is a public sample test API key.
// Don’t submit any personally identifiable information in requests made with this key.
// Sign in to see your own test API key embedded in code samples.
app.use(express.static("public"));
app.use(express.json());

app.post("/create-payment", async (req, res) => {

    /*
        If you have two or more "business_country" + "business_label" pairs configured in your Hyperswitch dashboard,
        please pass the fields business_country and business_label in this request body.
        For accessing more features, you can check out the request body schema for payments-create API here :
        https://api-reference.hyperswitch.io/docs/hyperswitch-api-reference/60bae82472db8-payments-create
    */

    fetch("https://sandbox.hyperswitch.io/payments", {
        method: "POST",
        headers: { "Content-Type": "application/json", 'api-key': "HYPERSWITCH_API_KEY" },
        body: JSON.stringify({
            currency: "USD",
            amount: 100,
        }),
    })
        .then(resp => resp.json())
        .then(data => {
            res.send({
                clientSecret: data.client_secret
            })
        })
})

app.listen(4242, () => console.log("Node server listening on port 4242!"));

import styles from '../styles/page.module.css'
import { loadHyper } from "@juspay-tech/hyper-js"
import { HyperElements } from "@juspay-tech/react-hyper-js";

import React, { useEffect, useState } from "react"
import CheckoutForm from './checkout-form'

export default function Home() {

  const [loadHyperValue, setLoadHyperValue] = useState()
  const [options, setOptions] = useState({})

  useEffect(() => {
    fetch("/create-payment", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ items: [{ id: "xl-tshirt" }] }),
    }).then((res) => res.json())
      .then((data) => {
        setOptions({
          clientSecret: data.clientSecret,
          appearance: {
            theme: "default"
          }
        })
      })
  }, [])

  useEffect(() => {
    setLoadHyperValue(loadHyper("HYPERSWITCH_PUBLISHABLE_KEY"));
  }, [])

  return (
    <div className={styles.main}>
      {Object.keys(options).length !== 0 ? <HyperElements options={options} hyper={loadHyperValue}>
        <CheckoutForm />
      </HyperElements> : <></>}
    </div>
  )
}

import React, { FormEvent, useEffect, useState } from "react"
import styles from '../styles/checkout.module.css'
import { useHyper, useWidgets, UnifiedCheckout } from "@juspay-tech/react-hyper-js";

const CheckoutForm: React.FC = ({ }) => {

    const hyper = useHyper();
    const widgets = useWidgets();

    const [isLoading, setIsLoading] = useState(false)
    const [isPaymentCompleted, setIsPaymentCompleted] = useState(false)
    const [message, setMessage] = useState("")

    const unifiedCheckoutOptions = {
        wallets: {
            walletReturnUrl: "http://localhost:3000",
        }
    };

    const handlePaymentStatus = (status: string) => {
        switch (status) {
            case "succeeded":
                setMessage("Successful");
                break;
            case "processing":
                setMessage("Your payment is processing.");
                break;
            case "requires_payment_method":
                setMessage("Your payment was not successful, please try again.");
                break;
            case "":
                break;
            default:
                setMessage("Something went wrong.");
                break;
        }
    }

    useEffect(() => {
        if (!hyper) {
            return;
        }

        const clientSecret = new URLSearchParams(window.location.search).get(
            "payment_intent_client_secret"
        );

        if (!clientSecret) {
            return;
        }

        hyper.retrievePaymentIntent(clientSecret).then((resp: any) => {
            const status = resp?.paymentIntent?.status
            if (status) {
                handlePaymentStatus(resp?.paymentIntent?.status)
            }
        })
    })

    const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault();

        setIsLoading(true);

        const response = await hyper.confirmPayment({
            widgets,
            confirmParams: {
                // Make sure to change this to your payment completion page
                return_url: "http://localhost:3000",
            },
            redirect: "if_required",
        });

        if (response) {
            if (response.status === "succeeded") {
                setMessage("Payment Successful");
            } else if (response.error) {
                setMessage(response.error.message);
            } else {
                setMessage("An unexpected error occurred.");
            }
        } else {
            setMessage("An unexpected error occurred.");
        }

        setIsLoading(false)
        setIsPaymentCompleted(true)
    }

    return (
        <form onSubmit={handleSubmit}>
            <UnifiedCheckout id="unified-checkout" options={unifiedCheckoutOptions} />
            <button className={styles.button} disabled={!hyper || !widgets || isPaymentCompleted}>
                {isLoading ? <div className={styles.spinner} id="spinner"></div> : <>Pay Now</>}
            </button>
            {/* Show any error or success messages */}
            {message && <div id="payment-message" className={styles.paymentMessage}>{message}</div>}
        </form>
    )
}

export default CheckoutForm;
